INSERT INTO packages (name, tier, guests, price, for_who, inclusions, sample_menu, popular, position) VALUES ('Gold', 'gold', 50, 15000, 'Debuts, christenings and company parties that want a full buffet and a crew to serve it.', '["5 main dishes", "2 desserts", "Steamed pandan rice", "Iced tea and water", "Buffet skirting and centrepiece", "Plates, glassware and cutlery", "2 food attendants"]', '["Braised Patatim with Cuapao", "Salted Egg Squid", "Chef Patrick’s Birthday Noodles", "Mandarin Chicken", "Three Kinds of Mushroom with Broccoli", "Coffee Jelly", "Almond Lychee"]', 1, 2);
INSERT INTO packages (name, tier, guests, price, for_who, inclusions, sample_menu, popular, position) VALUES ('Platinum', 'platinum', 100, 28000, 'Weddings and big celebrations, with styled tables, a full crew and a coordinator.', '["7 main dishes", "3 desserts", "Steamed pandan rice", "Drinks station", "Styled buffet and table centrepieces", "Plates, glassware and cutlery", "Full service crew and event coordinator"]', '["15-hour Slow Roast Beef Belly", "Crispy Pork Bagnet in Kare-Kare Sauce", "Mixed Seafood Hotpot", "Chef Patrick’s Cha Misua", "Yang Chow Fried Rice", "Assorted Kakanin"]', 0, 3);
